<script setup lang="ts">import type {Result} from '../types/entities';import PathRibbon from './PathRibbon.vue';defineProps<{result:Result}>();const groups:Record<string,string>={all:'全部观展路径',converted:'转化组',exited:'退出组'};</script><template><div class="medoid-panel"><section v-for="(title,key) in groups" :key="key"><p class="eyebrow">{{title}} / REPRESENTATIVE</p><template v-if="result.medoids[key]"><PathRibbon :path="result.medoids[key]!.path" :dictionary="result.dictionary"/><p class="annotation">{{result.medoids[key]!.journeys}}条路径 · 加权总距离{{result.medoids[key]!.weighted_total_distance}} · 平均距离{{result.medoids[key]!.mean_distance.toFixed(2)}}</p></template><p v-else class="annotation">该组没有观展路径，代表序列不可计算。</p></section></div></template>
